CREATE TABLE universities(university_id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL UNIQUE,short_name VARCHAR(30) UNIQUE,status ENUM('PENDING','APPROVED','REJECTED','INACTIVE') NOT NULL DEFAULT 'PENDING',requested_by BIGINT NULL,approved_by BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_at DATETIME NULL,FOREIGN KEY(requested_by) REFERENCES users(user_id) ON DELETE SET NULL,FOREIGN KEY(approved_by) REFERENCES users(user_id) ON DELETE SET NULL,INDEX idx_university_status(status,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO universities(name,short_name,status,approved_at) VALUES('University of Information Technology','UIT','APPROVED',UTC_TIMESTAMP());
ALTER TABLE users ADD COLUMN university_id BIGINT NULL,ADD COLUMN university_locked BOOLEAN NOT NULL DEFAULT FALSE,ADD COLUMN academic_info_locked BOOLEAN NOT NULL DEFAULT FALSE,ADD CONSTRAINT fk_users_university FOREIGN KEY(university_id) REFERENCES universities(university_id),ADD INDEX idx_users_university(university_id);
UPDATE users SET university_id=(SELECT university_id FROM universities WHERE short_name='UIT' LIMIT 1),university_locked=TRUE,academic_info_locked=(semester IS NOT NULL AND section_name IS NOT NULL) WHERE university_id IS NULL;
CREATE TABLE academic_change_requests(request_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,old_semester INT NULL,old_section VARCHAR(20),requested_semester INT NOT NULL,requested_section VARCHAR(20) NOT NULL,reason VARCHAR(1000) NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',pending_user_id BIGINT GENERATED ALWAYS AS(CASE WHEN status='PENDING' THEN user_id ELSE NULL END) STORED,reviewed_by BIGINT NULL,admin_note VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(reviewed_by) REFERENCES users(user_id) ON DELETE SET NULL,UNIQUE KEY uq_academic_one_pending(pending_user_id),INDEX idx_academic_status(status,created_at),INDEX idx_academic_user(user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
